package com.aryaa.sdm.service;
import org.springframework.stereotype.Service; import org.springframework.web.servlet.mvc.method.annotation.SseEmitter; import java.io.IOException; import java.util.List; import java.util.concurrent.CopyOnWriteArrayList;
@Service public class EventBroadcastService { private static final long TIMEOUT=30L*60*1000; private final List<SseEmitter> emitters=new CopyOnWriteArrayList<>(); public SseEmitter subscribe(){SseEmitter e=new SseEmitter(TIMEOUT);emitters.add(e);e.onCompletion(()->emitters.remove(e));e.onTimeout(()->emitters.remove(e));e.onError(x->emitters.remove(e));try{e.send(SseEmitter.event().name("connected").data("ok"));}catch(IOException x){emitters.remove(e);}return e;} public void broadcast(String name,Object payload){for(SseEmitter e:emitters){try{e.send(SseEmitter.event().name(name).data(payload));}catch(IOException x){e.complete();emitters.remove(e);}}}}